using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class BusSignGlowFix{static BusSignGlowFix(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!File.Exists("BusSignGlowFix.request"))return;File.Delete("BusSignGlowFix.request");try{var rs=UnityEngine.Object.FindObjectsOfType<MeshRenderer>(true);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/3D/Fbx/Materials/Bus Station.mat");material.SetFloat("_TerminalAccentGlow",4.5f);EditorUtility.SetDirty(material);AssetDatabase.SaveAssets();if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Bus shader error");var buses=rs.Where(r=>r.sharedMaterial&&r.sharedMaterial.name=="Bus Station").ToArray();var native=buses.First(r=>r.name=="polySurface248_phong3_0");var ctrl=UnityEngine.Object.FindObjectOfType<CityDayNightController>();bool night=ctrl.IsNight;try{ctrl.Apply(true);var b=native.bounds;var target=new Vector3(b.center.x,b.max.y-3,b.center.z);CityLightingBuilder.Capture(ctrl,Tuple.Create(target+new Vector3(100,10,12),Quaternion.LookRotation(new Vector3(-100,-10,-12))),"Bus-Terminal-Letter-Glow");}finally{ctrl.Apply(night);}File.WriteAllText("FinalEnvironmentRoadReview/BusSignGlowRepair.txt","SUCCESS BUS TERMINAL red lettering only now emits at night. Exact existing atlas island mask; original material/texture/geometry retained. No extra draws, lights or texture samples. Shader errors=0.");var mf=native.GetComponent<MeshFilter>();var data=typeof(FinalPNGCityDetails).GetMethod("Read",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic).Invoke(null,new object[]{mf.sharedMesh});var pp=(Vector3[])data.GetType().GetField("p").GetValue(data);var uu=(Vector2[][])data.GetType().GetField("uv").GetValue(data);File.WriteAllLines("FinalEnvironmentRoadReview/BusLetterUV.txt",pp.Select((p,i)=>new {p=mf.transform.TransformPoint(p),uv=uu[0][i]}).Where(q=>q.p.y>native.bounds.max.y-2).Select(q=>q.uv.ToString("F5")).Distinct());File.WriteAllLines("FinalEnvironmentRoadReview/BusGlowAudit.txt",buses.SelectMany(b=>rs.Where(r=>r.bounds.Intersects(b.bounds)).Select(r=>r.name+" | "+r.bounds+" | "+string.Join(",",r.sharedMaterials.Where(m=>m).Select(m=>m.name+" "+m.shader.name))))); }catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BusGlowAudit.txt",e.ToString());}}}
